    getSortedDomains() {
        const homeGenieAdapter = this.yot.getDefaultAdapter();
        const modules = this.sortedModules;
        if (!modules || modules.length === 0) {
            return [];
        }
        const groups = modules.reduce((acc, module) => {
            const key = module.Domain;
            if (!acc[key]) {
                acc[key] = [];
            }
            acc[key].push(module);
            return acc;
        }, {});
        const transformedGroups = Object.keys(groups).map(key => ({
            name: key,
            modules: groups[key].map((m) => homeGenieAdapter.getModuleByRef(m)).filter((m) => m.getWidgetData())
        }));
        return transformedGroups.filter(group => group.modules.length > 0);
    }
