  checkHasChildOfType(b, t) {
    let typeFound = b.type === 'function_call';

    if (!typeFound) {
      b.getChildren(false).map((child, index, array) => {
        if (child.type === t) {
          typeFound = true;
        }

        if (!typeFound && child.getChildren(false).length > 0) {
          typeFound = this.checkHasChildOfType(child, t);
        }
      });
    }

    return typeFound;
  }

