function drawBodySkeleton(canvas, ctx, poseData, cx, cy) {
  const skeletonConnections = [[0, 1], [0, 2], [1, 3], [2, 4], [0, 17], [5, 17], [6, 17], [5, 7], [6, 8], [5, 11], [6, 12], [7, 9], [8, 10], [11, 12], [11, 13], [12, 14], [13, 15], [14, 16] // Knees/Ankles
  ];
  const skeletonConnectionsColors = ["pink", "pink", "pink", "pink", "yellow", "#3B58E2", "#3B58E2", "cyan", "cyan", "cyan", "cyan", "yellow", "yellow", "violet", "violet", "violet", "purple", "purple" // Knees/Ankles
  ];
  ctx.strokeStyle = "cyan";
  ctx.lineWidth = 1.25;
  ctx.fillStyle = "deeppink"; // Style for the points

  for (const pose of poseData) {
    //Calculate neck position
    const leftShoulder = pose[5]?.Point;
    const rightShoulder = pose[6]?.Point;
    let neckX, neckY;

    if (leftShoulder && rightShoulder && !leftShoulder.IsEmpty && !rightShoulder.IsEmpty) {
      neckX = (leftShoulder.X + rightShoulder.X) / 2;
      neckY = (leftShoulder.Y + rightShoulder.Y) / 2;
    } // Draw the Neck point


    if (neckX !== undefined && neckY !== undefined) {
      ctx.beginPath();
      ctx.arc(neckX * cx, neckY * cy, 2, 0, 2 * Math.PI); // Draw a circle at the neck

      ctx.fill();
      ctx.closePath();
    } // Draw the neck point into pose array for connection


    pose[17] = {
      Index: 17,
      Point: {
        X: neckX ? neckX : 0,
        Y: neckY ? neckY : 0,
        IsEmpty: neckX === undefined || neckY === undefined
      },
      Confidence: (pose[5]?.Confidence || 0 + pose[6]?.Confidence || 0) / 2.0 //Average of shoulders.

    }; // Disegna i punti del corpo

    for (const part of pose) {
      if (part && part.Point && !part.Point.IsEmpty && part.Confidence > 0.5) {
        // Check for valid part and confidence
        const {
          X,
          Y
        } = part.Point; //Draw circle

        ctx.beginPath();
        ctx.arc(X * cx, Y * cy, 1.5, 0, 2 * Math.PI); // Draw a circle at each point

        ctx.fill();
        ctx.closePath();
      }
    } // Disegna le linee dello scheletro


    let idx = 0;

    for (const connection of skeletonConnections) {
      const [startIndex, endIndex] = connection;
      const startPart = pose[startIndex];
      const endPart = pose[endIndex]; // Check if parts are valid and, SPECIFICALLY, if neck is valid

      if (startPart && endPart && startPart.Point && endPart.Point && !startPart.Point.IsEmpty && !endPart.Point.IsEmpty && startPart.Confidence > 0.2 && endPart.Confidence > 0.2) {
        ctx.strokeStyle = skeletonConnectionsColors[idx];
        ctx.beginPath();
        ctx.moveTo(startPart.Point.X * cx, startPart.Point.Y * cy);
        ctx.lineTo(endPart.Point.X * cx, endPart.Point.Y * cy);
        ctx.stroke();
        ctx.closePath();
      }

      idx++;
    }
  }
}

function drawHandSkeleton(canvas, ctx, handPoseOutputData, // Usa il nuovo tipo
cx, cy, pointConfidenceThreshold = 0.25, lineConfidenceThreshold = 0.2) {
  // ----- Hand skelton (Indexes 0-20 MediaPipe) -----
  const HAND_CONNECTIONS = [// Palm / Wrist
  [0, 1], [0, 5], [0, 9], [0, 13], [0, 17], [5, 9], [9, 13], [13, 17], // Thumb
  [1, 2], [2, 3], [3, 4], // Index Finger
  [5, 6], [6, 7], [7, 8], // Middle Finger
  [9, 10], [10, 11], [11, 12], // Ring Finger
  [13, 14], [14, 15], [15, 16], // Pinky Finger
  [17, 18], [18, 19], [19, 20]]; // Colors

  const HAND_CONNECTION_COLORS = [// Palm / Wrist
  "white", "white", "white", "white", "white", "white", "white", "white", // Thumb
  "red", "red", "red", // Index Finger
  "lime", "lime", "lime", // Middle Finger
  "blue", "blue", "blue", // Ring Finger
  "yellow", "yellow", "yellow", // Pinky Finger
  "cyan", "cyan", "cyan"]; // Default styles

  ctx.lineWidth = 2;
  ctx.fillStyle = "orange";

  for (const handPose of handPoseOutputData) {
    // 1. Draw hand keypoints
    for (const keypoint of handPose) {
      // Controlla se il punto esiste, non è vuoto e ha confidenza sufficiente
      if (keypoint && keypoint.Point && !keypoint.Point.IsEmpty && keypoint.Confidence >= pointConfidenceThreshold) {
        const {
          X,
          Y
        } = keypoint.Point; // Disegna un piccolo cerchio per il punto chiave

        ctx.beginPath();
        ctx.arc(X * cx, Y * cy, 3, 0, 2 * Math.PI); // Raggio 3

        ctx.fill();
        ctx.closePath();
      }
    } // 2. Draw lines connections


    for (let i = 0; i < HAND_CONNECTIONS.length; i++) {
      const connection = HAND_CONNECTIONS[i];
      const [startIndex, endIndex] = connection;
      const startPointData = handPose[startIndex];
      const endPointData = handPose[endIndex]; // Check if both points are valid

      if (startPointData && endPointData && startPointData.Point && !startPointData.Point.IsEmpty && startPointData.Confidence >= lineConfidenceThreshold && endPointData.Point && !endPointData.Point.IsEmpty && endPointData.Confidence >= lineConfidenceThreshold) {
        // Set connection color
        ctx.strokeStyle = HAND_CONNECTION_COLORS[i] || "white"; // Usa bianco come fallback
        // Draw line

        ctx.beginPath();
        ctx.moveTo(startPointData.Point.X * cx, startPointData.Point.Y * cy);
        ctx.lineTo(endPointData.Point.X * cx, endPointData.Point.Y * cy);
        ctx.stroke();
        ctx.closePath();
      }
    }
  }
}

